/* Types */
export type AccountBilling = {
	checkoutUrl?: string | null,
	portalUrl?: string | null,
	upgradeTier?: string | null,
};

export type AccountCloudUsage = {
	today: AccountUsageWindow,
	sevenDays: AccountUsageWindow,
	thirtyDays: AccountUsageWindow,
};

export type AccountOrganization = {
	id: string,
	displayName?: string | null,
	role?: string | null,
};

export type AccountPlan = {
	name: string,
	tier?: string | null,
	state?: string | null,
	/**
	 *  False when the backend reports no dollar limit for this account: the UI
	 *  must then omit allowance figures instead of showing zeros.
	 */
	metered: boolean,
	monthlyAllowanceUsd?: number | null,
	usedUsd: number | null,
	remainingUsd?: number | null,
	resetsAt?: string | null,
	renewsAt?: string | null,
	/**  `cloud` or `dev_seed`; the UI labels the stand-in explicitly. */
	source: string,
};

export type AccountPlanOption = {
	tier: string,
	displayName: string,
	priceUsd: number | null,
	monthlyAllowanceUsd: number | null,
};

export type AccountSummary = {
	signedIn: boolean,
	state: string,
	environment: string,
	/**  Where the rendered plan came from, so the UI can label a dev stand-in. */
	source: string,
	accountId?: string | null,
	displayName?: string | null,
	email?: string | null,
	organization?: AccountOrganization | null,
	plan?: AccountPlan | null,
	cloudUsage?: AccountCloudUsage | null,
	billing: AccountBilling,
	catalog: AccountPlanOption[],
	/**  When the rendered cloud facts were fetched, for a `Last updated` line. */
	lastUpdated?: string | null,
	stale: boolean,
	error?: string | null,
	/**  `local_only` | `signed_out` | `active` | `revoked` | `offline` | `malformed` */
	sessionHealth: string,
	/**  `none` | `auth` | `entitlement` | `quota` | `outage` | `malformed` */
	failureKind: string,
	quotaExhausted: boolean,
	/**  `ok` | `stale` | `failed` — hosted usage vs the last successful snapshot. */
	reconciliation: string,
};

export type AccountUsageWindow = {
	events: number,
	/**  Finalized billed dollars. Never the sum of pending + billed. */
	costUsd: number | null,
	finalizedUsd: number | null,
	/**  Nominal minus billed for this window. Live estimates, not ledger truth. */
	pendingUsd: number | null,
	tokens: number,
	runtimeSeconds: number,
};

export type AfterImportAction = "keep" | "replace_aliases" | "remove_entries";

/**  Informative error payload serialized across the Tauri boundary. */
export type AppError = {
	code: string,
	message: string,
	/**  Developer-facing text. Keep out of user toasts. */
	detail: string,
};

export type AppEvent = {
	schemaVersion: string,
	sequence: number,
	eventId: string,
	sessionId?: string | null,
	sessionSequence?: number,
	runId?: string | null,
	source: EventSource,
	kind: string,
	payload: unknown,
	remoteSequence?: number,
	commandId?: string | null,
	createdAt: string,
};

export type ArtifactMutationReceipt = {
	operation: string,
	artifactId: string,
	digest?: string | null,
	bytes?: number | null,
	destination?: string | null,
	status: string,
};

export type AttachmentSource = "user_picker" | "recent_folder" | "agent_request" | "migrated_default";

export type AuthAction = "connect" | "wait" | "none" | "reauthenticate" | "retry";

export type AuthState = "disconnected" | "authenticating" | "ready" | "expiring" | "expired" | "refresh_failed";

export type BackendSettings = {
	configPath: string,
	envFile: string,
	profile: string,
	backendUrl: string,
	apiKeyEnv: string,
	apiKeyConfigured: boolean,
	apiKeyFingerprint: string | null,
	apiKeySource: string | null,
	workerKeyConfigured: boolean,
	openrouterApiKeyConfigured: boolean,
	openrouterApiKeyFingerprint: string | null,
	openrouterApiKeySource: string | null,
	/**
	 *  `[models.default]` from Workshop's config.toml. Provider order is a
	 *  fallback chain, not a request to silently change providers mid-turn.
	 */
	defaultModel: DefaultModelSettings,
};

export type BackendSettingsUpdate = {
	profile: string,
	backendUrl: string,
	envFile: string,
	apiKeyEnv: string,
	/**
	 *  Write-only. It may arrive from the renderer for manual API-key setup,
	 *  but is never returned by any settings command.
	 */
	apiKey: string | null,
};

export type BeginResult = {
	authorizeUrl: string,
	mode: string,
};

export type BillingAction = "upgrade" | "manage";

export type BrowserRuntimeStatus = {
	phase: string,
	detail: string,
	backendPresent: boolean,
	nodePresent: boolean,
	playwrightPresent: boolean,
	chromiumPresent: boolean,
	nodeVersion: string | null,
	backendPath: string,
	profileRoot: string,
	allowedOrigins: string[],
	defaultLocalOrigins: string[],
};

export type CapabilitySummary = {
	id: string,
	secretId: string,
	runId: string,
	recipeId: string,
	provider: string,
	status: string,
	maxCalls: number,
	usedCalls: number,
	maxCostUsd: number | null,
	usedCostUsd: number | null,
	usedInputTokens: number,
	usedOutputTokens: number,
	expiresAt: string,
	displaySuffix: string | null,
};

export type CheckpointInferRequest = {
	checkpointId: string,
	family: string,
	body: unknown,
};

export type CodexApprovalDecisionRequest = {
	sessionId: string,
	approvalId: string,
	decision: string,
};

export type CodexSessionInfo = {
	sessionId: string,
	threadId: string,
	turnId: string | null,
};

export type CodexSessionRecord = {
	sessionId: string,
	threadId: string,
	workspace: string,
	model: string,
	providerName: string,
	providerTitle: string,
	baseUrl: string,
	status: string,
	title?: string | null,
	titleOrigin?: string | null,
	presentationEmotion?: string | null,
	presentationSummary?: string | null,
	approvalPolicy?: string,
	sandbox?: string,
	/**  This Mac Laguna adapter catalog id. `None` is the base model. */
	adapter?: string | null,
	/**
	 *  Set when the previous process died holding this chat's turn. It is what
	 *  lets the sidebar say "Workshop exited while this task was running"
	 *  instead of silently showing an idle chat — or, worse, a live one.
	 */
	recovery?: RecoveryNotice | null,
};

export type CodexSessionRequest = {
	sessionId: string,
};

export type CodexSessionStartRequest = {
	sessionId: string,
	workspace: string,
	baseUrl: string,
	apiKey?: string,
	model: string,
	providerName: string | null,
	providerTitle: string | null,
	providerEnvKey: string | null,
	approvalPolicy: string | null,
	sandbox: string | null,
	serviceTier: string | null,
	threadId: string | null,
	multiAgentVersion: MultiAgentVersion | null,
	autoCompactTokenLimit?: number,
	/**
	 *  Rust-populated exact roots for this conversation. Renderer input is
	 *  discarded by `prepare_codex_start` before launch.
	 */
	writableRoots?: string[],
	/**
	 *  Catalog identity (`sha256:…`) of a This Mac Laguna-compatible LoRA.
	 *  `None` is the base Laguna XS weights. Renderer-owned; never forwarded
	 *  into the Codex app-server provider payload.
	 */
	adapter?: string | null,
};

export type CodexSteerRequest = {
	sessionId: string,
	text: string,
};

export type CodexThreadItemsRequest = {
	sessionId: string,
	threadId: string,
	cursor?: string | null,
	limit?: number | null,
};

export type CodexThreadReadRequest = {
	sessionId: string,
	threadId: string,
	includeTurns?: boolean,
};

/**
 *  Typed failure so the renderer can react to a lost app-server without
 *  parsing free-form text or leaking raw ids into a toast.
 */
export type CodexTurnFailure = {
	code: string,
	message: string,
	sessionId: string,
	/**  Developer-facing text. The renderer keeps this out of user surfaces. */
	detail: string,
};

/**
 *  One atomic renderer intent: make sure the app-server is attached for this
 *  session and start the turn. The renderer never observes the intermediate
 *  state where an attachment exists but the turn has not started.
 */
export type CodexTurnSendRequest = {
	start: CodexSessionStartRequest,
	prompt: string,
	effort: string | null,
	/**
	 *  When the destination model differs from the live attachment, compact the
	 *  thread on the *source* model before rebind. Renderer sets this from the
	 *  send-time state machine (`modelSwitchPlan`): true only when the thread
	 *  has history; empty threads skip compact.
	 */
	compactBeforeModelSwitch?: boolean,
	/**  Same ownership as [`CodexTurnStartRequest::client_message_id`]. */
	clientMessageId?: string | null,
};

export type CodexTurnStartRequest = {
	sessionId: string,
	prompt: string,
	effort: string | null,
	/**
	 *  Renderer optimistic bubble id. When present, the journalled
	 *  `message.created` reuses it so the host event collapses onto the
	 *  already-visible bubble instead of minting a second UUID.
	 */
	clientMessageId?: string | null,
};

